// Exact backward coverability for a finite guarded-reset color patch times
// monotone current-token age-tail resources. A cap is UNKNOWN, never a proof.
#include <bits/stdc++.h>
using namespace std;using U=uint64_t;
struct O{int c;vector<int>I,V;};struct E{int f,t,a,op;U k,v,flip,clear,reset;};
struct N{int p;vector<int>r;U mask,val;int par,ei,depth;bool live;array<U,4>support;array<long long,5>sums;};
int main(int ac,char**av){ifstream f(av[1]);string fmt;int m,np,ne,no,ni,ng,nb;f>>fmt>>m>>np>>ne>>no>>ni>>ng>>nb;assert(fmt=="COLOROPS"&&nb<63);int d=m*5;assert(d<=256);U all=(1ULL<<nb)-1;vector<vector<pair<U,U>>>init(np);for(int i=0,p;i<ni;i++){U k,v;f>>p>>k>>v;init[p].push_back({k&all,v&k&all});}vector<int>goals(ng);vector<char>isgoal(np);for(int&p:goals){f>>p;isgoal[p]=1;}vector<O>ops(no);for(auto&o:ops){f>>o.c;o.I.resize(d);o.V.resize(m);for(auto&x:o.I)f>>x;for(auto&x:o.V)f>>x;assert(f&&o.c>=0&&o.c<=4);}vector<E>es(ne);vector<vector<int>>inc(np);for(int i=0;i<ne;i++){auto&e=es[i];f>>e.f>>e.t>>e.a>>e.op>>e.k>>e.v>>e.flip>>e.clear>>e.reset;assert(f&&e.op>=0&&e.op<no);e.k&=all;e.v&=e.k;e.clear&=all;e.reset&=e.clear;e.flip&=all;inc[e.t].push_back(i);}size_t cap=ac>2?stoull(av[2]):1000000;vector<long long>weights(d,1);if(ac>4){ifstream w(av[4]);for(auto&x:weights)w>>x;assert(w);}vector<U>reach,fixedMask(np),fixedValue(np);vector<char>hasReach(np);uint32_t reachWords=0;size_t reachPruned=0,fixedDropped=0;
const U patternOne[6]={0xAAAAAAAAAAAAAAAAULL,0xCCCCCCCCCCCCCCCCULL,0xF0F0F0F0F0F0F0F0ULL,0xFF00FF00FF00FF00ULL,0xFFFF0000FFFF0000ULL,0xFFFFFFFF00000000ULL};
if(ac>5){ifstream ri(av[5],ios::binary);char magic[8];uint32_t head[3];ri.read(magic,8);ri.read((char*)head,sizeof(head));assert(ri&&string(magic)=="COLRCH1"&&head[0]==unsigned(nb)&&head[1]==unsigned(np));reachWords=head[2];assert(reachWords==((1ULL<<nb)+63)/64);reach.resize(size_t(np)*reachWords);ri.read((char*)reach.data(),reach.size()*8);assert(ri);for(int p=0;p<np;p++){U loOR=0,loAND=63,hiOR=0,hiAND=~0ULL;for(U w=0;w<reachWords;w++){U bits=reach[size_t(p)*reachWords+w];if(!bits)continue;hasReach[p]=1;hiOR|=w;hiAND&=w;for(int b=0;b<6;b++){if(bits&patternOne[b])loOR|=1ULL<<b;if(bits&~patternOne[b])loAND&=~(1ULL<<b);}}if(hasReach[p]){U a=(hiOR<<6)|loOR,b=(hiAND<<6)|loAND;fixedMask[p]=~(a^b)&all;fixedValue[p]=b&fixedMask[p];}}}
auto intersectsReach=[&](int p,U mask,U val){if(reach.empty())return true;if(!hasReach[p]||((val^fixedValue[p])&mask&fixedMask[p]))return false;mask&=~fixedMask[p];val&=mask;if(!mask)return true;U pat=~0ULL;for(int b=0;b<min(nb,6);b++)if(mask&(1ULL<<b))pat&=(val&(1ULL<<b))?patternOne[b]:~patternOne[b];U hk=mask>>6,hv=val>>6;for(U w=0;w<reachWords;w++)if(!((w^hv)&hk)&&(reach[size_t(p)*reachWords+w]&pat))return true;return false;};
vector<N>ns;vector<vector<int>>basis(np);using Item=tuple<long long,int,int>;priority_queue<Item,vector<Item>,greater<Item>>todo;size_t retired=0,tests=0,dense=0;int hit=-1;U initialcolor=0;
auto decorate=[&](N&n){n.support.fill(0);n.sums.fill(0);for(int j=0;j<d;j++){if(n.r[j])n.support[j/64]|=1ULL<<(j%64);n.sums[j%5]+=n.r[j];}};
auto dominates=[&](const N&a,const N&b){tests++;if((a.mask&b.mask)!=a.mask||((a.val^b.val)&a.mask))return false;for(int j=0;j<5;j++)if(a.sums[j]>b.sums[j])return false;for(int j=0;j<4;j++)if(a.support[j]&~b.support[j])return false;dense++;for(int j=0;j<d;j++)if(a.r[j]>b.r[j])return false;return true;};
auto add=[&](int p,vector<int>r,U mask,U val,int par,int ei){if(!intersectsReach(p,mask,val)){reachPruned++;return;}if(!reach.empty()){fixedDropped+=__builtin_popcountll(mask&fixedMask[p]);mask&=~fixedMask[p];val&=mask;}N n{p,move(r),mask,val&mask,par,ei,par>=0?ns[par].depth+1:0,true,{},{}};decorate(n);auto&v=basis[p];for(int id:v)if(ns[id].live&&dominates(ns[id],n))return;for(int id:v)if(ns[id].live&&dominates(n,ns[id])){ns[id].live=false;retired++;if(ns[id].par>=0)vector<int>().swap(ns[id].r);}if(v.size()>32){vector<int>w;for(int id:v)if(ns[id].live)w.push_back(id);v.swap(w);}int id=ns.size();long long score=__builtin_popcountll(mask);for(int j=0;j<d;j++)score+=weights[j]*n.r[j];int dep=n.depth;ns.push_back(move(n));v.push_back(id);todo.emplace(score,dep,id);if(ns[id].sums[0]==0)for(auto[k,w]:init[p])if(!((ns[id].val^w)&ns[id].mask&k)){hit=id;initialcolor=(w&k)|(ns[id].val&~k);break;}};
for(int p:goals)add(p,vector<int>(d),0,0,-1,-1);size_t pops=0;int maxdepth=0;
while(!todo.empty()&&hit<0){auto[score,dep,id]=todo.top();todo.pop();if(!ns[id].live)continue;pops++;maxdepth=max(maxdepth,dep);if(pops%100000==0)cerr<<"pops "<<pops<<" labels "<<ns.size()<<" live "<<ns.size()-retired<<" queue "<<todo.size()<<" cost "<<score<<" depth "<<dep<<" tests "<<tests<<" dense "<<dense<<" reach_pruned "<<reachPruned<<" fixed_dropped "<<fixedDropped<<"\n";int p=ns[id].p;auto r=ns[id].r;U mask=ns[id].mask,val=ns[id].val;for(int ei:inc[p]){auto&e=es[ei];auto&o=ops[e.op];if((val^e.reset)&mask&e.clear)continue;U k=mask&~e.clear,w=(val^e.flip)&k;if((w^e.v)&k&e.k)continue;k|=e.k;w=(w|(e.v&e.k))&k;vector<int>prev(d);for(int z=0;z<m;z++){int s=5*z,c=o.c;prev[s]=o.I[s]+max({0,r[s]-o.V[z],c<4?r[s+c+1]:0});for(int j=1;j<5;j++)prev[s+j]=o.I[s+j]+(j+c<5?r[s+j+c]:0);if(prev[s]>1000000){cout<<"status RESOURCE_LIMIT\n";return 0;}}add(e.f,move(prev),k,w,id,ei);if(ns.size()>=cap){cout<<"status CAP labels "<<ns.size()<<" live "<<ns.size()-retired<<" maxdepth "<<maxdepth<<"\n";return 0;}if(hit>=0)break;}}
if(hit<0){cout<<"status EXHAUSTED_NO_ZERO_INITIAL labels "<<ns.size()<<" live "<<ns.size()-retired<<" maxdepth "<<maxdepth<<"\n";if(ac>3){ofstream o(av[3]);if(!reach.empty())o<<"REACH_RESTRICTED "<<av[5]<<"\n";o<<m<<" "<<np<<" "<<nb<<" "<<ns.size()-retired<<"\n";for(auto&n:ns)if(n.live){o<<n.p<<" "<<n.mask<<" "<<n.val;for(int x:n.r)o<<" "<<x;o<<"\n";}}return 0;}
cout<<"status COLOR_AGE_WITNESS labels "<<ns.size()<<" live "<<ns.size()-retired<<" maxdepth "<<maxdepth<<"\n";int u=hit;U color=initialcolor;vector<int>mark(d);cout<<"start "<<ns[u].p<<" "<<color<<"\n";int steps=0;while(ns[u].par>=0){auto&n=ns[u];auto&e=es[n.ei];auto&o=ops[e.op];assert(((color^e.v)&e.k)==0);cout<<"EDGE "<<n.ei<<" "<<e.f<<" "<<e.t<<" "<<e.a<<" "<<color;for(int x:mark)cout<<" "<<x;cout<<"\n";for(int j=0;j<d;j++)assert(mark[j]>=o.I[j]);vector<int>after(d);for(int z=0;z<m;z++){int s=z*5,mn=mark[s]-o.I[s];for(int j=0;j<=o.c;j++)after[s+j]=mark[s]-o.I[s]+o.V[z];for(int j=o.c+1;j<5;j++){int k=j-o.c;mn=min(mn,mark[s+k]-o.I[s+k]);after[s+j]=mn;}}mark.swap(after);color=((color^e.flip)&~e.clear)|e.reset;u=n.par;steps++;}assert(isgoal[ns[u].p]);cout<<"goal "<<ns[u].p<<" "<<color<<" steps "<<steps<<"\n";
}
